import clsx from 'clsx'
import type { ComponentPropsWithoutRef } from 'react'

export type CardProps = ComponentPropsWithoutRef<'div'> & { padded?: boolean }

export function Card({ padded = true, className, ...rest }: CardProps) {
  return <div className={clsx('card', padded && 'card--padded', className)} {...rest} />
}

